describe('Form Autocomplete Attributes', () => {
    beforeEach(() => {
        cy.visit('/form-page'); // Replace with the actual URL of the form page
    });

    it('should have correct autocomplete attribute for email input', () => {
        cy.get('input[type="email"]')
            .should('have.attr', 'autocomplete', 'email');
    });

    it('should have correct autocomplete attribute for username input', () => {
        cy.get('input[name="username"]')
            .should('have.attr', 'autocomplete', 'username');
    });
});
